
/* JSND: one sample-based sound engine. Plays only while the SND toggle is on. */
(function(){
var DATA={"tick":"","hover":"","hold":"","holdDone":"","release":"","slash":"","gate":"","mask1":"","mask2":"","mask3":"","unmasked":"","shatter":"","nameReveal":"","on":"","off":"","bg":"","rain":"","thunder1":"","thunder2":"","thunder3":""};
var VOL={rain:1,thunder1:.7,thunder2:.85,thunder3:1,tick:.5,hover:.3,hold:.55,holdDone:.85,release:.5,slash:.75,gate:.9,mask1:.75,mask2:.65,mask3:.65,unmasked:.95,shatter:.6,nameReveal:.85,on:.6,off:.5};
var JIT={tick:1,hover:1,shatter:1,release:1};
var AC=null,master=null,buf={},loading=null,bg=null,hold=null,lastAt=0,bgWant=false;
function enabled(){var b=document.getElementById('snd');return !!b&&b.getAttribute('aria-pressed')==='true'}
function ctx(){if(!AC){try{AC=new(window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=1;master.connect(AC.destination)}catch(e){return null}}
 if(AC.state==='suspended'){try{AC.resume()}catch(e){}}return AC}
function decode(k){return new Promise(function(res){try{var b=atob(DATA[k]),u=new Uint8Array(b.length);for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
 AC.decodeAudioData(u.buffer,function(d){buf[k]=d;res()},function(){res()})}catch(e){res()}})}
function load(){if(!ctx())return Promise.resolve();if(!loading)loading=Promise.all(Object.keys(DATA).map(decode));return loading}
function src(k,loop){var s=AC.createBufferSource();s.buffer=buf[k];s.loop=!!loop;return s}
function play(k,o){o=o||{};if(!o.force&&!enabled())return;if(!ctx())return;
 if(!buf[k]){load().then(function(){if(buf[k]&&(o.force||enabled()))go(k,o)});return}go(k,o)}
function go(k,o){var s=src(k),g=AC.createGain(),v=(o.vol==null?1:o.vol)*(VOL[k]||.6);
 g.gain.value=v;if(JIT[k])s.playbackRate.value=.95+Math.random()*.1;
 s.connect(g);g.connect(master);s.start(AC.currentTime+(o.delay||0));lastAt=performance.now()}
function fadeStop(h,t){if(!h)return;try{h.g.gain.cancelScheduledValues(AC.currentTime);h.g.gain.setValueAtTime(h.g.gain.value,AC.currentTime);h.g.gain.linearRampToValueAtTime(0,AC.currentTime+t);h.s.stop(AC.currentTime+t+.03)}catch(e){}}
function holdStart(){if(!enabled()||!ctx())return;fadeStop(hold,.05);hold=null;
 var begin=function(){if(!buf.hold)return;var s=src('hold'),g=AC.createGain();g.gain.value=VOL.hold;s.connect(g);g.connect(master);s.start();hold={s:s,g:g};lastAt=performance.now()};
 if(buf.hold)begin();else load().then(begin)}
function holdStop(p){var h=hold;hold=null;if(h)fadeStop(h,.12);if(p>.08)play('release')}
function holdDone(skip){var h=hold;hold=null;if(h)fadeStop(h,.25);if(!skip)play('holdDone')}
var rainSrc=null,stormWant=false;
function rainStart(){if(rainSrc||!enabled()||!ctx())return;load().then(function(){if(rainSrc||!stormWant||!enabled()||!buf.rain)return;var s=src('rain',true),g=AC.createGain();g.gain.value=0;s.connect(g);g.connect(master);s.start();g.gain.setTargetAtTime(.3,AC.currentTime,1.6);rainSrc={s:s,g:g};if(bg)bg.g.gain.setTargetAtTime(.06,AC.currentTime,1.2)})}
function rainStop(){if(bg&&AC)bg.g.gain.setTargetAtTime(.12,AC.currentTime,1.5);if(!rainSrc)return;var r=rainSrc;rainSrc=null;try{r.g.gain.setTargetAtTime(0,AC.currentTime,1.2);r.s.stop(AC.currentTime+4.5)}catch(e){}}
function storm(on){stormWant=on;if(on)rainStart();else rainStop()}
function ambient(on){bgWant=on;
 if(on){if(!ctx())return;load().then(function(){if(!bgWant||bg||!buf.bg)return;var s=src('bg',true),g=AC.createGain();g.gain.value=0;s.connect(g);g.connect(master);s.start();
  g.gain.setTargetAtTime(stormWant?.06:.12,AC.currentTime,.8);bg={s:s,g:g};if(stormWant)rainStart()})}
 else{if(rainSrc){var r0=rainSrc;rainSrc=null;try{r0.g.gain.setTargetAtTime(0,AC.currentTime,.25);r0.s.stop(AC.currentTime+1.2)}catch(e){}}if(bg){var b=bg;bg=null;try{b.g.gain.setTargetAtTime(0,AC.currentTime,.25);b.s.stop(AC.currentTime+1.2)}catch(e){}}if(hold){fadeStop(hold,.1);hold=null}}}
document.addEventListener('visibilitychange',function(){if(!AC)return;try{if(document.hidden)AC.suspend();else if(enabled())AC.resume()}catch(e){}});
/* tiny UI sounds: tick on press, hover on mouse over */
var SEL='a[href],button,[role=button],[role=tab],summary',SKIP='#snd,.tgt,#ninja,.mk-tab,.lbx';
function ui(e){var t=e.target&&e.target.closest&&e.target.closest(SEL);return t&&!t.closest(SKIP)&&!t.disabled?t:null}
document.addEventListener('click',function(e){if(!enabled()||!ui(e))return;if(performance.now()-lastAt<140)return;play('tick')});
var lastHover=0;
document.addEventListener('pointerover',function(e){if(e.pointerType!=='mouse'||!enabled())return;var t=ui(e);if(!t||t.contains(e.relatedTarget))return;var n=performance.now();if(n-lastHover<90)return;lastHover=n;play('hover')});
/* haptics: light, rate-limited, respects reduced motion; every other vibrate() call also feeds the limiter */
var HR=matchMedia('(prefers-reduced-motion: reduce)').matches,lastHap=0,_vb=navigator.vibrate?navigator.vibrate.bind(navigator):null;
if(_vb)navigator.vibrate=function(p){if(p!==0&&!(p&&p.length===1&&p[0]===0))lastHap=performance.now();return _vb(p)};
function hap(p,gap){if(!_vb||HR)return;if(performance.now()-lastHap<(gap==null?60:gap))return;try{navigator.vibrate(p)}catch(e){}}
window.HAP=hap;
document.addEventListener('click',function(e){if(ui(e))hap(6,140)});
window.JSND={play:play,holdStart:holdStart,holdStop:holdStop,holdDone:holdDone,ambient:ambient,storm:storm,unlock:function(){ctx();return load()},enabled:enabled};
})();
